-- Hosbah (MH-575 H7): one row per raw exception occurrence (a span event named "exception", or an
-- OTLP log record with severity >= ERROR), kept 30 days so an issue's "latest example" has a real
-- stacktrace to show; apm_issues.count/last_seen is the cheap aggregate used everywhere else.
-- stacktrace is capped to 16KB by the ingest path before it ever reaches this column.
ALTER TABLE apm_exception_events ADD CONSTRAINT apm_exception_events_stacktrace_check CHECK (length(stacktrace) <= 16384);
CREATE INDEX apm_exception_events_issue_idx ON apm_exception_events (team_id, app_id, issue_id, created_at DESC);
CREATE INDEX apm_exception_events_created_idx ON apm_exception_events (created_at);
